-- MY GYM London - 100 more exercises for the library, 10 for each body part
-- (chest, back, shoulders, biceps, triceps, legs, glutes, abs, lower back, full body)
-- Gym equipment only: barbell, dumbbells, kettlebells, cables, Smith bar, pull-up bar, bodyweight.
-- Paste into Supabase Dashboard -> SQL Editor -> Run (safe to re-run: skips any name already in the library, any capitals).
-- Biceps and triceps are both in the "Arms" group; abs are "Core".
with new_rows(name, muscle_group, equipment, how_to, sort) as (values
-- Chest (10)
('Single-arm cable fly','Chest','Cable','Handle at chest height, step forward, sweep the handle across the body with a soft elbow, return slowly.',264),
('Incline cable press','Chest','Cable','Bench at 30 degrees facing away from low pulleys, press the handles up and together, lower under control.',265),
('Decline cable fly','Chest','Cable','Pulleys set high, lean forward, sweep the handles down and together to the lower chest.',266),
('Smith decline press','Chest','Smith bar','On a decline bench under the Smith bar, lower to the lower chest and press up.',267),
('Wide-grip bench press','Chest','Barbell','Hands wider than shoulders, lower the bar to the mid-chest and press up with the shoulder blades tucked.',268),
('Kettlebell floor press','Chest','Kettlebell','Lie on the floor holding a kettlebell, lower the elbow to the floor and press up.',269),
('Alternating dumbbell bench press','Chest','Dumbbell','Hold both dumbbells over the chest, lower one at a time and press it back up while the other stays locked out.',270),
('Hand-release push-up','Chest','Bodyweight','Lower the chest to the floor, lift the hands off for a moment, then press back up.',271),
('Spiderman push-up','Chest','Bodyweight','As you lower into a push-up, bring one knee towards the same elbow, then press up and switch sides.',272),
('Paused bench press','Chest','Barbell','Lower the bar to the chest, pause for one second without bouncing, then press up.',273),
-- Back (10), including the back flies
('Chest-supported dumbbell reverse fly','Back','Dumbbell','Chest on an incline bench, arms hanging, raise the dumbbells out to the sides squeezing the shoulder blades.',274),
('Single-arm cable reverse fly','Back','Cable','Cable at shoulder height, pull the handle across and back with a soft elbow, squeeze the upper back, return slowly.',275),
('Single-arm lat pulldown','Back','Cable','Seated at the high pulley with one handle, pull the elbow down to the ribs and control the way up.',276),
('Underhand cable row','Back','Cable','Seated, palms facing up, pull the bar to the stomach with the elbows close to the body.',277),
('Smith reverse-grip row','Back','Smith bar','Hinge to a flat back, underhand grip on the Smith bar, row to the lower ribs and lower slowly.',278),
('Kettlebell gorilla row','Back','Kettlebell','Wide stance, hinge down with a kettlebell in each hand, row one then the other to the hip.',279),
('Incline bench Y raise','Back','Dumbbell','Chest on an incline bench, raise light dumbbells in a Y shape above the head, thumbs up, lower slowly.',280),
('Dumbbell deadlift','Back','Dumbbell','Dumbbells at the sides, flat back, push the floor away and stand tall, then lower with control.',281),
('Smith shrug','Back','Smith bar','Hold the Smith bar at the thighs, lift the shoulders straight up, pause, lower slowly.',282),
('Dead hang','Back','Pull-up bar','Hang from the bar with straight arms and shoulders away from the ears, and hold.',283),
-- Shoulders (10)
('Kettlebell press','Shoulders','Kettlebell','Kettlebell at the shoulder, press straight overhead with the wrist straight, lower under control.',284),
('Bottoms-up kettlebell press','Shoulders','Kettlebell','Hold the kettlebell upside down by the handle, press overhead keeping it steady, lower slowly.',285),
('Z press','Shoulders','Barbell','Sit on the floor with legs straight, press the bar overhead without leaning back.',286),
('Seated dumbbell lateral raise','Shoulders','Dumbbell','Seated on a bench, raise the dumbbells out to the sides to shoulder height and lower slowly.',287),
('Leaning dumbbell lateral raise','Shoulders','Dumbbell','Hold a support and lean away, raise one dumbbell out to the side to shoulder height, lower slowly.',288),
('Cable Y raise','Shoulders','Cable','Low pulleys, raise the handles up and out in a Y shape to head height, lower slowly.',289),
('Barbell front raise','Shoulders','Barbell','Hold the bar at the thighs, raise it in front to shoulder height with straight arms, lower slowly.',290),
('Smith upright row','Shoulders','Smith bar','Hold the Smith bar at the thighs, pull up towards the chest with the elbows leading, lower slowly.',291),
('Dumbbell upright row','Shoulders','Dumbbell','Dumbbells at the thighs, pull up towards the chest with the elbows high, lower slowly.',292),
('Cuban press','Shoulders','Dumbbell','Upright row the dumbbells, rotate the forearms up so they point to the ceiling, press overhead, reverse.',293),
-- Biceps (10)
('Smith drag curl','Arms','Smith bar','Curl the Smith bar up while sliding it along the body with the elbows moving back, lower slowly.',294),
('Kettlebell hammer curl','Arms','Kettlebell','Hold the kettlebell by the sides of the handle, curl with elbows pinned, lower slowly.',295),
('Behind-the-back cable curl','Arms','Cable','Low pulley behind you, step forward and curl the handle up with the elbow at the side.',296),
('High cable double biceps curl','Arms','Cable','Both pulleys at head height, arms out to the sides, curl the handles towards the ears and return slowly.',297),
('21s barbell curl','Arms','Barbell','Seven reps from the bottom to halfway, seven from halfway to the top, then seven full reps.',298),
('Wide-grip barbell curl','Arms','Barbell','Hands wider than shoulders, curl the bar up with elbows pinned and lower slowly.',299),
('Close-grip barbell curl','Arms','Barbell','Hands closer than shoulder width, curl the bar up with elbows pinned and lower slowly.',300),
('Incline hammer curl','Arms','Dumbbell','Seated on an incline bench, palms facing in, curl the dumbbells up and lower slowly.',301),
('Bayesian cable curl','Arms','Cable','Facing away from a low pulley, arm behind the body, curl the handle forward and up, lower slowly.',302),
