('Barbell skull crusher','Arms','Barbell','Lying on a bench, lower the bar towards the forehead by bending the elbows, then extend the arms.',304),
('Smith JM press','Arms','Smith bar','Close grip on the Smith bar, lower to the upper chest with the elbows forward, press up.',305),
('Barbell overhead triceps extension','Arms','Barbell','Holding the bar overhead, bend the elbows to lower it behind the head, then straighten the arms.',306),
('Single-arm overhead cable extension','Arms','Cable','Face away from a low pulley, handle overhead, straighten the arm and return slowly.',307),
('Cross-body cable triceps extension','Arms','Cable','High pulley with a handle, push down and across the body keeping the elbow pinned.',308),
('Kettlebell overhead triceps extension','Arms','Kettlebell','Hold the kettlebell overhead with both hands, lower it behind the head, then straighten the arms.',309),
('Weighted bench dip','Arms','Dumbbell','Hands on a bench, a dumbbell on the lap, lower the body by bending the elbows and press up.',310),
('Decline dumbbell triceps extension','Arms','Dumbbell','On a decline bench, lower the dumbbells beside the head by bending the elbows, then extend.',311),
('Kneeling cable pushdown','Arms','Cable','Kneel facing a high pulley, push the rope or bar down until the arms are straight, return slowly.',312),
('Dumbbell cross-body triceps extension','Arms','Dumbbell','Lying on a bench, lower the dumbbell across the body towards the opposite shoulder, then extend.',313),
-- Legs (10)
('Smith front squat','Legs','Smith bar','Bar across the front of the shoulders under the Smith bar, squat to depth and stand up tall.',314),
('Smith hack squat','Legs','Smith bar','Bar behind the legs, feet slightly forward, squat down and stand up keeping the chest tall.',315),
('Overhead squat','Legs','Barbell','Bar locked out overhead with a wide grip, squat to depth keeping the arms straight and the chest up.',316),
('Box squat','Legs','Barbell','Squat back to a box or bench, pause lightly on it, then stand up.',317),
('Pause squat','Legs','Barbell','Squat to the bottom, hold for two seconds, then drive up.',318),
('Curtsy lunge','Legs','Dumbbell','Step one leg back and across behind the other, lower the back knee, then return to standing.',319),
('Deficit reverse lunge','Legs','Dumbbell','Front foot on a low step, step the other leg back and lower the knee, then return.',320),
('Kettlebell sumo deadlift','Legs','Kettlebell','Wide stance with the kettlebell between the feet, flat back, stand up squeezing the glutes.',321),
('Barbell step-up','Legs','Barbell','Bar on the upper back, step onto a bench with one foot, drive up and lower slowly.',322),
('Seated dumbbell calf raise','Legs','Dumbbell','Seated with a dumbbell on the knees, raise the heels high, pause, then lower for a stretch.',323),
-- Glutes (10)
('Barbell glute bridge','Glutes','Barbell','Lie on the floor with the bar over the hips, lift the hips until the body is straight and squeeze.',324),
('Dumbbell hip thrust','Glutes','Dumbbell','Upper back on a bench, a dumbbell on the hips, drive the hips up and squeeze at the top.',325),
('Dumbbell glute bridge','Glutes','Dumbbell','Lie on the floor with a dumbbell on the hips, lift the hips and squeeze the glutes.',326),
('Smith glute bridge','Glutes','Smith bar','Lie under the Smith bar with it across the hips, lift the hips and squeeze at the top.',327),
('Single-leg Smith hip thrust','Glutes','Smith bar','Upper back on a bench, bar across the hips, drive up on one leg and squeeze.',328),
('Cable glute kickback','Glutes','Cable','Ankle strap on a low pulley, kick the leg straight back keeping the torso still, return slowly.',329),
('Cable standing hip abduction','Glutes','Cable','Ankle strap on a low pulley, lift the leg out to the side without leaning, return slowly.',330),
('Frog pump','Glutes','Bodyweight','Lie on your back with the soles of the feet together and knees out, lift the hips and squeeze.',331),
('Kettlebell single-leg deadlift','Glutes','Kettlebell','Hold a kettlebell, hinge on one leg with the other leg back and a flat back, then stand tall.',332),
('Lateral dumbbell step-up','Glutes','Dumbbell','Stand side-on to a bench, step up sideways with the near foot, drive up and lower slowly.',333),
-- Abs (10) -> Core
('Low-to-high cable woodchop','Core','Cable','Cable set low, pull the handle up and across the body, rotating through the trunk, return slowly.',334),
('Kettlebell Russian twist','Core','Kettlebell','Seated with feet raised, hold a kettlebell and rotate it from side to side.',335),
('Dumbbell woodchop','Core','Dumbbell','Hold a dumbbell with both hands, swing it diagonally from high to low, rotating through the trunk.',336),
('Weighted plank','Core','Dumbbell','In a forearm plank with a dumbbell on the back, keep the body straight and hold.',337),
('Copenhagen plank','Core','Bodyweight','Side plank with the top leg resting on a bench, lift the hips and hold.',338),
('Plank leg lift','Core','Bodyweight','In a plank, lift one leg a little off the floor, hold briefly, then switch legs.',339),
('Dumbbell crunch','Core','Dumbbell','Hold a dumbbell at the chest, curl the shoulders off the floor and lower slowly.',340),
('Standing cable crunch','Core','Cable','Hold the rope at the head, crunch the ribs towards the hips, return slowly.',341),
('Weighted dead bug','Core','Dumbbell','Lying on your back holding a dumbbell above the chest, lower the opposite arm and leg, then switch.',342),
('Bear crawl','Core','Bodyweight','On hands and toes with knees just off the floor, crawl forward and back with a flat back.',343),
-- Lower back (10)
('Cable good morning','Lower back','Cable','Rope behind the neck from a low pulley, hinge at the hips with a flat back and stand tall.',344),
('Dumbbell superman','Lower back','Dumbbell','Lie face down holding light dumbbells, lift the chest and legs, hold, lower slowly.',345),
('Prone leg raise','Lower back','Bodyweight','Lie face down, lift one straight leg off the floor, lower slowly, then switch.',346),
('Cat-cow','Lower back','Bodyweight','On hands and knees, arch the back up, then lower it and lift the chest, moving slowly.',347),
('Jefferson curl','Lower back','Kettlebell','Light kettlebell, slowly roll the spine down one bone at a time, then roll back up.',348),
('Back extension hold','Lower back','Bodyweight','On a back extension bench, lift the torso until the body is straight and hold.',349),
('Superman pull','Lower back','Bodyweight','Lie face down with arms forward, lift the chest and pull the elbows back to the ribs, then reach forward.',350),
('Reverse snow angel','Lower back','Bodyweight','Lie face down, lift the arms and sweep them from the sides up overhead and back.',351),
('Bench reverse hyperextension','Lower back','Bodyweight','Lie face down on a bench with the hips at the edge, lift the straight legs until in line with the body.',352),
('Hip hinge drill','Lower back','Bodyweight','Push the hips back with a flat back until the hamstrings stretch, then drive the hips forward to stand.',353),
-- Full body (10)
('Kettlebell snatch','Full body','Kettlebell','Swing the kettlebell up in one smooth movement to overhead, punching the hand through, then lower it.',354),
('Kettlebell clean','Full body','Kettlebell','Swing the kettlebell up and rotate the hand around it so it rests at the shoulder, then lower.',355),
('Single-arm kettlebell swing','Full body','Kettlebell','Hinge and drive the hips forward to swing the kettlebell to chest height with one hand.',356),
('Kettlebell thruster','Full body','Kettlebell','Squat holding the kettlebell at the shoulder, stand up and press it overhead in one movement.',357),
('Dumbbell snatch','Full body','Dumbbell','Dumbbell between the feet, pull it up and punch overhead in one movement, then lower.',358),
('Barbell thruster','Full body','Barbell','Front squat with the bar at the shoulders, stand up and press it overhead in one movement.',359),
('Barbell hang clean','Full body','Barbell','From the hips, pull the bar up and catch it at the shoulders in a quarter squat, then lower.',360),
('Man maker','Full body','Dumbbell','Push-up on dumbbells, row each side, jump the feet in, stand and press the dumbbells overhead.',361),
('Kettlebell high pull','Full body','Kettlebell','Hinge, drive the hips forward and pull the kettlebell up to chest height with the elbow high.',362),
('Barbell complex','Full body','Barbell','Without putting the bar down, do a row, a clean, a front squat and a press, then repeat.',363)
)
insert into public.exercises (name, muscle_group, equipment, how_to, sort)
select n.name, n.muscle_group, n.equipment, n.how_to, n.sort
from new_rows n
where not exists (select 1 from public.exercises e where lower(e.name) = lower(n.name));
